def comps(g,v=0):
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==v and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                touch=False
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if not(0<=ny<h and 0<=nx<w): touch=True; continue
                        if g[ny][nx]==v and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                res.append((c,touch))
    return res
